import {uid,clone,find,isLocked} from '../document/model.js';
import {evaluated} from './evaluate.js';
const freshTrack=track=>track.map(k=>({...clone(k),id:uid()}));
export function layerBlocks(n,p){if(n.referenceFrames)return n.blocks??[{id:'reference-'+n.id,name:n.name,start:n.referenceFrames.start,end:Math.min(p.duration,n.referenceFrames.start+n.referenceFrames.duration),props:[],kind:'reference'}];const props=Object.keys(n.tracks||{}).filter(k=>n.tracks[k].length);if(Array.isArray(n.blocks))return n.blocks;if(!props.length)return [];const keys=props.flatMap(prop=>n.tracks[prop]),start=Math.min(...keys.map(k=>k.time)),end=Math.max(start+1/p.fps,...keys.map(k=>k.time));return [{id:'animation-'+n.id,name:n.name+' animation',start,end:Math.min(p.duration,end),props,kind:'animation'}];}
export function persistBlocks(n,p){n.blocks??=clone(layerBlocks(n,p));return n.blocks;}
export function isolateBlock(n,p,id){const b=persistBlocks(n,p).find(b=>b.id===id);if(!b)throw Error('Select an animation block.');b.tracks??=Object.fromEntries(b.props.map(prop=>[prop,freshTrack(n.tracks[prop]||[])]));return b;}
export function splitBlock(n,p,id,time){const blocks=persistBlocks(n,p),index=blocks.findIndex(b=>b.id===id),b=blocks[index],cut=Math.round(time*p.fps)/p.fps;if(!b||cut<=b.start||cut>=b.end)throw Error('Place the playhead inside the selected block before splitting.');const right={...clone(b),id:uid(),name:b.name+' · part 2',start:cut};if(right.tracks)for(const prop of Object.keys(right.tracks))right.tracks[prop]=freshTrack(right.tracks[prop]);b.end=cut;blocks.splice(index+1,0,right);return right.id;}
function holdCut(n,start,end,value,props){if(end<=start)return;(n.blockCuts??=[]).push({start,end,values:Object.fromEntries(props.map(prop=>[prop,clone(value[prop])]))});}
export function trimBlock(n,p,id,start,end){const b=persistBlocks(n,p).find(b=>b.id===id);if(!b||!Number.isFinite(start)||!Number.isFinite(end)||start<b.start-.00001||end>b.end+.00001||end<=start)throw Error('Trim boundaries must stay inside the selected block.');start=Math.round(start*p.fps)/p.fps;end=Math.round(end*p.fps)/p.fps;if(end<=start)throw Error('Keep at least one frame.');if(b.kind!=='reference'){const before=evaluated(n,Math.max(0,b.start-1/p.fps)),tail=evaluated(n,end-1/p.fps);holdCut(n,b.start,start,before,b.props);holdCut(n,end,b.end,tail,b.props);}b.start=start;b.end=end;if(n.referenceFrames)n.referenceFrames.visibleRanges=n.blocks.map(x=>({start:x.start,end:x.end}));return b;}
export function removeBlock(n,p,id){const blocks=persistBlocks(n,p),b=blocks.find(x=>x.id===id);if(!b)return;if(b.kind!=='reference')holdCut(n,b.start,b.end,evaluated(n,Math.max(0,b.start-1/p.fps)),b.props);n.blocks=blocks.filter(x=>x.id!==id);if(n.referenceFrames)n.referenceFrames.visibleRanges=n.blocks.map(x=>({start:x.start,end:x.end}));}
export function copyBlock(n,p,id){const b=layerBlocks(n,p).find(x=>x.id===id);if(!b)throw Error('Select a block first.');if(b.kind==='reference')throw Error('Use Duplicate to reuse a baked reference layer.');return {kind:'animation',name:b.name,object:n.id,duration:b.end-b.start,fps:p.fps,sourceStart:b.start,tracks:b.props.map(prop=>({prop,keys:freshTrack(b.tracks?.[prop]||n.tracks[prop]||[])}))};}
export function pasteBlock(p,data,start){const n=find(p,data?.object);if(!n||isLocked(p,n.id))throw Error('The copied layer is missing or locked.');start=Math.round(start*p.fps)/p.fps;const end=start+Math.round(data.duration*p.fps)/p.fps;if(start<0||end>600)throw Error('Paste must stay within 10 minutes.');const blocks=persistBlocks(n,p);p.duration=Math.max(p.duration,end);const b={id:uid(),name:data.name+' copy',start,end,kind:'animation',props:data.tracks.map(t=>t.prop),tracks:Object.fromEntries(data.tracks.map(t=>[t.prop,t.keys.map(k=>({...clone(k),id:uid(),time:k.time-data.sourceStart+start}))]))};blocks.push(b);return b.id;}
export function moveBlock(n,p,id,start){const b=persistBlocks(n,p).find(b=>b.id===id);if(!b)throw Error('Select a block.');if(b.kind==='reference')throw Error('Trim the reference block to edit its timing.');start=Math.round(start*p.fps)/p.fps;const length=b.end-b.start;if(start<0||start+length>p.duration)throw Error('The block must fit inside the composition.');const source=clone(b.tracks??Object.fromEntries(b.props.map(prop=>[prop,n.tracks[prop]||[]]))),oldStart=b.start;holdCut(n,b.start,b.end,evaluated(n,Math.max(0,b.start-1/p.fps)),b.props);b.start=start;b.end=start+length;b.tracks=Object.fromEntries(Object.entries(source).map(([prop,keys])=>[prop,keys.map(k=>({...clone(k),id:uid(),time:k.time+start-oldStart}))]));return b;}
